{
  "strategy_name": "dual_sma_trend_following",
  "description": "Daily dual SMA trend following strategy. Buys when 20-day SMA crosses above 60-day SMA, sells when it crosses below. No leverage used.",
  "version": "1.0",
  "market": {
    "symbol": "SPY",
    "timeframe": "1d",
    "start_date": "2020-01-01",
    "end_date": "2024-12-31"
  },
  "indicators": [
    {"name": "SMA", "params": {"window": 20}, "alias": "sma_20"},
    {"name": "SMA", "params": {"window": 60}, "alias": "sma_60"}
  ],
  "entry_rules": [
    {"type": "cross_over", "left": "sma_20", "right": "sma_60"}
  ],
  "exit_rules": [
    {"type": "cross_under", "left": "sma_20", "right": "sma_60"}
  ],
  "risk_control": {
    "position_size": 1.0,
    "stop_loss": 0.05,
    "take_profit": null,
    "max_drawdown_limit": 0.15,
    "allow_short": false,
    "leverage": 1.0
  }
}

